// Package catalog holds the embedded model catalog and its loader.
//
// models.json is generated by scripts/gen-catalog from catalog/sources.yaml
// and the public Ollama registry. Do not edit it by hand.
package catalog

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"sync"
)

//go:embed models.json
var embeddedJSON []byte

// Variant is one quantization of a model, pullable by Tag.
type Variant struct {
	Tag       string  `json:"tag"`
	SizeBytes uint64  `json:"size_bytes"`
	Bits      float64 `json:"bits"`
	Quant     string  `json:"quant"`
}

// Model is one catalog entry with the architecture facts the estimator needs.
type Model struct {
	Family        string    `json:"family"`
	Name          string    `json:"name"`
	ParamsB       float64   `json:"params_b"`
	ActiveParamsB float64   `json:"active_params_b"`
	Layers        int       `json:"layers"`
	KVHeads       int       `json:"kv_heads"`
	HeadDim       int       `json:"head_dim"`
	MaxCtx        int       `json:"max_ctx"`
	Quality       int       `json:"quality"`
	KVQuantOK     bool      `json:"kv_quant_ok"`
	Tasks         []string  `json:"tasks,omitempty"` // subset of Tasks
	Variants      []Variant `json:"variants"`
}

// Tasks lists the task tags a catalog entry may carry: coding (code-tuned
// model), reasoning (has a thinking mode) and vision (accepts images in Ollama).
var Tasks = []string{"coding", "reasoning", "vision"}

// ValidTask reports whether t is one of Tasks.
func ValidTask(t string) bool {
	for _, k := range Tasks {
		if k == t {
			return true
		}
	}
	return false
}

// HasTask reports whether m is tagged with task t.
func (m Model) HasTask(t string) bool {
	for _, k := range m.Tasks {
		if k == t {
			return true
		}
	}
	return false
}

// FilterTask returns the models tagged with task t, or ms unchanged when t is empty.
func FilterTask(ms []Model, t string) []Model {
	if t == "" {
		return ms
	}
	var out []Model
	for _, m := range ms {
		if m.HasTask(t) {
			out = append(out, m)
		}
	}
	return out
}

// UnmarshalJSON decodes a Model, defaulting kv_quant_ok to true when absent.
func (m *Model) UnmarshalJSON(b []byte) error {
	type plain Model
	aux := struct {
		*plain
		KVQuantOK *bool `json:"kv_quant_ok"`
	}{plain: (*plain)(m)}
	if err := json.Unmarshal(b, &aux); err != nil {
		return err
	}
	m.KVQuantOK = aux.KVQuantOK == nil || *aux.KVQuantOK
	return nil
}

// Load decodes a catalog JSON array. It does not validate; call Validate.
func Load(r io.Reader) ([]Model, error) {
	var ms []Model
	dec := json.NewDecoder(r)
	dec.DisallowUnknownFields()
	if err := dec.Decode(&ms); err != nil {
		return nil, fmt.Errorf("catalog: decode: %w", err)
	}
	return ms, nil
}

var (
	embeddedOnce   sync.Once
	embeddedModels []Model
)

// Embedded returns a copy of the catalog compiled into the binary.
// It panics if the embedded JSON is malformed, which TestEmbeddedValid guards.
func Embedded() []Model {
	embeddedOnce.Do(func() {
		ms, err := Load(bytes.NewReader(embeddedJSON))
		if err != nil {
			panic(err)
		}
		embeddedModels = ms
	})
	out := make([]Model, len(embeddedModels))
	for i, m := range embeddedModels {
		m.Variants = append([]Variant(nil), m.Variants...)
		out[i] = m
	}
	return out
}

// Validate checks every entry for usable values. Errors name the model's tag.
func Validate(ms []Model) error {
	seen := map[string]string{}
	for _, m := range ms {
		id := m.Name
		if len(m.Variants) > 0 {
			id = m.Variants[0].Tag
		}
		switch {
		case len(m.Variants) == 0:
			return fmt.Errorf("catalog: model %q has no variants", m.Name)
		case m.Family == "" || m.Name == "":
			return fmt.Errorf("catalog: %s: empty family or name", id)
		case m.ParamsB <= 0 || m.ActiveParamsB <= 0:
			return fmt.Errorf("catalog: %s: params_b and active_params_b must be > 0", id)
		case m.ActiveParamsB > m.ParamsB:
			return fmt.Errorf("catalog: %s: active_params_b %.2f > params_b %.2f", id, m.ActiveParamsB, m.ParamsB)
		case m.Layers <= 0:
			return fmt.Errorf("catalog: %s: layers must be > 0", id)
		case m.KVHeads <= 0:
			return fmt.Errorf("catalog: %s: kv_heads must be > 0", id)
		case m.HeadDim <= 0:
			return fmt.Errorf("catalog: %s: head_dim must be > 0", id)
		case m.MaxCtx <= 0:
			return fmt.Errorf("catalog: %s: max_ctx must be > 0", id)
		case m.Quality < 0 || m.Quality > 100:
			return fmt.Errorf("catalog: %s: quality %d outside 0-100", id, m.Quality)
		}
		for _, t := range m.Tasks {
			if !ValidTask(t) {
				return fmt.Errorf("catalog: %s: unknown task %q (valid: %s)", id, t, strings.Join(Tasks, ", "))
			}
		}
		for _, v := range m.Variants {
			switch {
			case v.Tag == "":
				return fmt.Errorf("catalog: model %q has a variant with empty tag", m.Name)
			case v.SizeBytes == 0:
				return fmt.Errorf("catalog: %s: size_bytes must be > 0", v.Tag)
			case v.Bits <= 0:
				return fmt.Errorf("catalog: %s: bits must be > 0", v.Tag)
			case v.Quant == "":
				return fmt.Errorf("catalog: %s: empty quant", v.Tag)
			}
			if prev, dup := seen[v.Tag]; dup {
				return fmt.Errorf("catalog: duplicate tag %s (models %q and %q)", v.Tag, prev, m.Name)
			}
			seen[v.Tag] = m.Name
		}
	}
	return nil
}

// QuantPenalty is the quality adjustment for a quantization level:
// q8 0, q6 -1, q5 -2, q4 -3, q3 -8, q2 -15. Unknown or unquantized types get 0.
func QuantPenalty(quant string) int {
	q := strings.TrimPrefix(strings.ToLower(quant), "i") // iq4_xs ranks with q4
	switch {
	case strings.HasPrefix(q, "q8"):
		return 0
	case strings.HasPrefix(q, "q6"):
		return -1
	case strings.HasPrefix(q, "q5"):
		return -2
	case strings.HasPrefix(q, "q4"):
		return -3
	case strings.HasPrefix(q, "q3"):
		return -8
	case strings.HasPrefix(q, "q2"):
		return -15
	}
	return 0
}
